insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('86482a8f-da92-58ff-a74b-77b404d6d37e', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'Identify a disadvantage of being a sole trader.', '["Accounts must be published for the public","Shares can be bought by anyone at any time","Unlimited liability for the business''s debts","All profit is shared among the shareholders"]'::jsonb, 'A sole trader has unlimited liability, so personal assets can be taken to pay business debts.', false, 'paper', '1.4 Types of business organisation', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('86482a8f-da92-58ff-a74b-77b404d6d37e', 2, 'Disadvantages that score: unlimited liability, hard to raise finance, long hours and no one to share the workload, the business may end if the owner is ill or dies. For ''explain'', add the consequence (e.g. the owner could lose their house).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('f468d17b-8f28-5e11-a937-71ed5870f5c1', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'Explain one advantage of a franchise to the franchisee.', '["They use a well-known brand, so customers already trust it","They have complete freedom to change their products and prices","They keep all of the profit and pay nothing to the brand","They never need any money to open their franchise shop"]'::jsonb, 'A known brand brings customers straight away, so the risk of failure is lower.', false, 'paper', '1.4 Types of business organisation', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('f468d17b-8f28-5e11-a937-71ed5870f5c1', 0, 'Advantages that score: an established brand and reputation, training and support from the franchisor, national advertising, a lower risk of failure. Disadvantages to balance: fees and royalties, little freedom.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('376ef665-36b8-5b92-a864-4473724ec6d9', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'What is a joint venture?', '["Two or more businesses working together on a shared project","A business owned and run entirely by the government","A sole trader taking on a partner to share profits","One business buying all of the shares of another business outright"]'::jsonb, 'A joint venture is two businesses sharing the costs, risks and profits of one project.', false, 'paper', '1.4 Types of business organisation', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('376ef665-36b8-5b92-a864-4473724ec6d9', 0, 'Define it, then give a benefit (shared costs and risks, combined expertise, entry into a new market) and a drawback (shared profits, possible disagreements).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('39e989a1-4c10-50af-aadb-9f5fa9acf22b', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'Why is survival often the main objective of a new business?', '["New businesses are not legally allowed to make any profit in their first year","It must cover its costs and build customers before aiming for growth","Survival is the only objective a business is allowed to have","New businesses never face any competition from other firms"]'::jsonb, 'A new business must first stay open; growth and profit come once it''s established.', false, 'paper', '1.5 Business and stakeholder objectives', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('39e989a1-4c10-50af-aadb-9f5fa9acf22b', 1, 'Explain the link: a new business has high start-up costs, few customers and strong competition, so staying open comes first. Then say objectives change over time (survival → growth → profit/market share).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('84e8c7a2-2754-5eac-ac45-5f3a68dc4499', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'Which is an example of conflicting stakeholder objectives?', '["Shareholders want lower costs; employees want higher wages","The government wants tax; the business pays its tax on time","Customers want quality; managers want a good reputation","Suppliers want orders; the business wants reliable supplies"]'::jsonb, 'Paying higher wages raises costs and reduces the profit shareholders want.', false, 'paper', '1.5 Business and stakeholder objectives', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('84e8c7a2-2754-5eac-ac45-5f3a68dc4499', 0, 'Name the two stakeholders, say what each wants, and explain WHY they clash. In a ''discuss'' question, suggest how the business might balance them (e.g. a bonus linked to productivity).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('d2d8568a-0a2e-5775-a6a1-23ada02013e4', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'Identify an external stakeholder.', '["Customers","Managers","Owners","Employees"]'::jsonb, 'Customers are outside the business, so they are external stakeholders.', false, 'paper', '1.5 Business and stakeholder objectives', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('d2d8568a-0a2e-5775-a6a1-23ada02013e4', 0, 'Internal stakeholders work in or own the business (owners, managers, employees). External ones are outside it (customers, suppliers, lenders, government, local community). Remember: stakeholder ≠ shareholder.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
